producer.initTransactions();          // 시작할 때 한 번

try {
    producer.beginTransaction();

    producer.send(new ProducerRecord<>("orders", key, orderJson));
    producer.send(new ProducerRecord<>("inventory", key, invJson));
    producer.send(new ProducerRecord<>("audit", key, auditJson));

    producer.commitTransaction();     // 셋 다 보이거나
} catch (ProducerFencedException | OutOfOrderSequenceException e) {
    producer.close();                 // 회복 불가 -- 새로 만들어야 한다
} catch (KafkaException e) {
    producer.abortTransaction();      // 셋 다 안 보인다
}
